/* detail.js — detailed answers. The short `solution` of a question always exists; a longer explanation (idea, steps, why the
 * other choices fail, the trap) is stored per chapter in data/detail-c/<chapter>.js (GENERATED by tools/build.py from data/detail/*.json)
 * and loaded the first time a solution of that chapter is shown. Offline, the files come from the service worker's cache.
 *   S.detail.html(q, opts)   the solution block for one question (bank question object), with the long explanation when it is loaded
 *   S.detail.get(qid)        the stored explanation or null
 * No DOM except the loader's <script> tag; S.detail.html returns a string. */
(function (S) {
  'use strict';
  const u = S.u;
  const state = {}; // chapter id -> 'loading' | 'ready' | 'failed'

  const chapterOf = (qid) => String(qid).replace(/-[a-z]+\d+$/, '');
  const table = () => window.DETAIL_C || {};

  function get(qid) {
    const t = table()[chapterOf(qid)];
    return t && t[qid] ? t[qid] : null;
  }

  // Loads the chapter's explanations (once). The caller is redrawn when they arrive.
  const has = (ch) => (S.DETAIL_CHAPTERS || []).indexOf(ch) >= 0;

  function ensure(ch) {
    if (!has(ch)) return; // no detailed answers written for this chapter yet: nothing to load
    if (table()[ch]) {
      state[ch] = 'ready';
      return;
    }
    if (state[ch] === 'loading' || state[ch] === 'failed') return;
    state[ch] = 'loading';
    const s = document.createElement('script');
    s.src = 'data/detail-c/' + ch + '.js';
    s.async = true;
    s.onload = () => {
      state[ch] = table()[ch] ? 'ready' : 'failed';
      if (S.app && S.app.refresh) S.app.refresh(false);
    };
    s.onerror = () => {
      state[ch] = 'failed';
      s.remove();
      if (S.app && S.app.refresh) S.app.refresh(false);
    };
    document.head.appendChild(s);
  }

  // The solution block. opts: { ok: true|false|null (was her answer right?), chapter link: default on }
  function html(q, opts) {
    opts = opts || {};
    const ch = q.ch || chapterOf(q.id);
    ensure(ch);
    const d = get(q.id);
    const link = opts.noLink ? '' : '<a class="sol-link" data-act="go" data-to="#/revise/' + u.esc(ch) + '">Revise this chapter</a>';
    if (!d) {
      const wait = state[ch] === 'loading' ? '<p class="small muted">Loading the full explanation…</p>' : '';
      return '<div class="tc-sol sol" data-testid="solution"><b class="small">Solution</b><p>' + u.esc(q.solution) + '</p>' + wait + link + '</div>';
    }
    return (
      '<div class="tc-sol sol sol-long" data-testid="solution">' +
      '<p class="sol-ans"><span class="lbl">Correct answer</span><b>' + u.esc(d.answer) + '</b></p>' +
      '<h4 class="sol-h">The idea</h4><p>' + u.esc(d.idea) + '</p>' +
      '<h4 class="sol-h">Step by step</h4><ol class="sol-steps">' + d.steps.map((x) => '<li>' + u.esc(x) + '</li>').join('') + '</ol>' +
      (d.others ? '<h4 class="sol-h">Why not the other choices</h4><p>' + u.esc(d.others) + '</p>' : '') +
      (d.trap ? '<p class="sol-trap"><b>Watch out:</b> ' + u.esc(d.trap) + '</p>' : '') + link + '</div>'
    );
  }

  S.detail = { get: get, ensure: ensure, html: html, state: (ch) => state[ch] || (table()[ch] ? 'ready' : 'idle') };
})((window.SOS = window.SOS || {}));
